function proyeccionCaja(n) {
  const hoyS = hoyLocal(); const meses = []; for (let k = 1; k <= n; k++) { const d = parseFecha(hoyS.slice(0, 7) + '-01'); d.setUTCMonth(d.getUTCMonth() + k); meses.push(isoFecha(d).slice(0, 7)); }
  const bg = balanceGeneral(hoyS); let saldo = bg.corr.filter(x => ['1105', '1110'].includes(x.cod)).reduce((s, x) => s + x.v, 0); let ref = 0; try { ref = precioRefCarga().v; } catch (e) {}
  let cur = null; try { cur = curvaMaduracion(); } catch (e) {}
  const kgMes = {}; if (cur && cur.lotesP) cur.lotesP.forEach(lp => (lp.sem || []).forEach((kg, k) => { const m = sumarDias(hoyS, k * 7 + 3).slice(0, 7); kgMes[m] = (kgMes[m] || 0) + kg; }));
  const tarifa = trabajadores.length ? trabajadores.reduce((s, t) => s + n0(t.tarifaPorKg), 0) / trabajadores.length : 700; const fc = n0(cfgMapa().factorPergamino) || 5;
  const cart = cartera(hoyS); const nom = empleados.reduce((s, e) => s + n0(e.salario) * (1 + (/prestaci|servicio|jornal/i.test(e.contrato || '') ? 0 : n0(cfgConta().factorPrestacional))), 0);
  return meses.map(m => { const cer = kgMes[m] || 0; const ventasV = cer / fc / CARGA * ref; const cobros = cart.cxc.filter(x => x.vence.slice(0, 7) === m || (m === meses[0] && x.vence < m)).reduce((s, x) => s + x.saldo, 0);
    const prov = cart.cxp.filter(x => x.vence.slice(0, 7) === m || (m === meses[0] && x.vence < m)).reduce((s, x) => s + x.saldo, 0); const plan = planesAgro.filter(a => a.anio === Number(m.slice(0, 4)) && a.mes === Number(m.slice(5)) && !a.otId).reduce((s, a) => s + costoActividad(a).total, 0) + ordenes.filter(o => !['Cerrada', 'Cancelada'].includes(o.estado) && String(o.fechaProgramada).slice(0, 7) === m).reduce((s, o) => s + n0((o.presupuesto || {}).total), 0);
    const recol = cer * tarifa; const entra = ventasV + cobros, sale = recol + plan + nom + prov; saldo += entra - sale; return { m, ventas: ventasV, cobros, recol, plan, nomina: nom, prov, entra, sale, saldo }; });
}
